export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"id","term":"Airdrop","aka":["airdrop kripto","airdrop token"],"short":"Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi.","body":["Proyek membagikan airdrop untuk mendistribusikan token secara luas, memberi penghargaan pada pengguna awal, atau menarik komunitas. Kriteria bisa berupa pemakaian protokol sebelum tanggal snapshot, memegang token tertentu, atau menyelesaikan tugas. Kriterianya sering baru diumumkan setelah snapshot diambil.",["Di Indonesia banyak orang aktif berburu airdrop dengan mencoba protokol baru, testnet, atau aplikasi berbasis tugas. Hal ini butuh waktu dan ",["biaya gas","gas-fee"],", dan tidak ada jaminan ada token di akhirnya. Banyak airdrop juga punya jadwal vesting sehingga tidak semua token bisa langsung dijual."],["Airdrop juga menjadi umpan favorit penipu. Token asing yang tiba-tiba muncul di dompet atau situs klaim palsu bisa meminta Anda menandatangani approve yang menguras dompet. Klaim hanya dari tautan resmi proyek, dan jangan pernah memasukkan ",["seed phrase","seed-phrase"],"."]],"example":["Misalkan sebuah protokol membagikan 40 juta token kepada 20.000 dompet yang memenuhi syarat secara merata, sehingga setiap dompet mendapat 2.000 token. Jika token diperdagangkan di 0,15 ",["USDT","usdt"]," saat dibuka, nilai bagian Anda 300 USDT. Namun jika Anda sebelumnya menghabiskan 45 USDT untuk biaya gas selama berburu, hasil bersihnya 255 USDT, dan nilainya bisa berubah cepat jika banyak penerima langsung menjual."],"mistakes":["Berinteraksi dengan token asing yang muncul di dompet atau membuka situs yang tertera di nama token itu.","Memasukkan seed phrase ke formulir klaim airdrop.","Menghabiskan banyak biaya gas untuk berburu airdrop tanpa menghitung bahwa hasilnya tidak dijamin."],"faq":[{"q":"Apakah airdrop benar-benar gratis?","a":"Tokennya diberikan tanpa dibeli, tetapi berburu airdrop sering membutuhkan biaya gas dan waktu. Pajak atas token yang diterima juga bisa berlaku tergantung negara."},{"q":"Bagaimana mengenali airdrop palsu?","a":"Waspadai token tak dikenal di dompet, tautan dari DM, dan situs yang meminta seed phrase atau approve tak terbatas. Cek pengumuman di kanal resmi proyek."}],"title":"Apa itu airdrop kripto? Arti dan cara aman klaim","description":"Arti airdrop kripto, cara proyek menentukan penerima, biaya berburu airdrop, dan cara mengenali airdrop palsu.","related":[["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui."],["governance-token","Governance token (token tata kelola)","Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak."],["launchpool","Launchpool","Launchpool adalah fitur bursa yang memberi Anda token proyek baru secara gratis sebagai imbalan karena mengunci aset tertentu, seperti BNB atau stablecoin, selama periode singkat."],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"id","term":"Centralized exchange (CEX)","aka":["CEX","exchange terpusat","bursa kripto"],"short":"Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC.","body":[["Contoh CEX global adalah Binance, OKX, Bybit, Bitget, dan Coinbase, sementara di Indonesia ada pedagang ",["aset kripto","cryptocurrency"]," lokal yang terdaftar dan diawasi OJK. CEX menyediakan ",["order book","order-book"],", ",["pasangan perdagangan","trading-pair"]," dengan rupiah atau ",["USDT","usdt"],", serta produk seperti futures, ",["staking","staking"],", dan ",["copy trading","copy-trading"],"."],"Kelebihannya adalah kemudahan: deposit rupiah lewat transfer bank atau P2P, likuiditas tinggi, dan layanan pelanggan. Kekurangannya, Anda tidak memegang private key. Jika exchange diretas, membekukan akun, atau bangkrut, akses ke dana Anda bisa terganggu.","Biaya, aset yang tersedia, batas penarikan, dan perlindungan pengguna berbeda di setiap exchange. Perhatikan struktur biaya maker dan taker, biaya penarikan per jaringan, ketersediaan proof of reserves, serta izin operasional di negara Anda."],"example":"Misalkan Anda membeli BTC senilai 1.000 USDT di dua exchange. Exchange A mengenakan biaya taker 0,10%, jadi biayanya 1 USDT. Exchange B mengenakan 0,05%, jadi biayanya 0,50 USDT. Jika Anda bertransaksi 20 kali sebulan dengan ukuran sama, selisihnya 10 USDT per bulan. Lalu jika biaya penarikan BTC di A 0,0002 BTC dan di B 0,0001 BTC, selisih itu juga perlu dihitung. Angka ini ilustrasi, bukan tarif exchange tertentu.","mistakes":["Menyimpan seluruh aset jangka panjang di satu exchange tanpa memahami risiko kustodian.","Hanya membandingkan biaya trading tanpa melihat biaya penarikan dan spread.","Mengunduh aplikasi exchange dari tautan iklan atau pesan, bukan dari sumber resmi."],"faq":[{"q":"Apa beda CEX dan DEX?","a":"CEX dijalankan perusahaan yang menyimpan dana Anda dan mewajibkan KYC. DEX berjalan di smart contract, dan Anda bertransaksi langsung dari dompet pribadi."},{"q":"Apakah aman menyimpan kripto di exchange?","a":"Exchange besar umumnya punya sistem keamanan berlapis, tetapi risiko peretasan, pembekuan, atau kebangkrutan tetap ada. Banyak pengguna menyimpan dana jangka panjang di dompet pribadi."}],"title":"Apa itu centralized exchange (CEX)? Arti dan risikonya","description":"Arti centralized exchange atau CEX, cara kerjanya, kelebihan dan risikonya, serta biaya yang perlu Anda bandingkan.","related":[["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree."],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"id","term":"Support dan resistance","aka":["support","resistance","level support","area resisten"],"short":"Support dan resistance adalah area harga di mana penurunan cenderung tertahan karena banyak pembeli (support) atau kenaikan cenderung tertahan karena banyak penjual (resistance).","body":["Support terbentuk ketika harga beberapa kali turun ke area yang sama lalu memantul naik. Resistance adalah kebalikannya: harga berkali-kali gagal menembus area tertentu. Lebih tepat memandangnya sebagai zona, bukan satu angka persis, karena order trader tersebar di sekitar level itu.",["Ketika resistance ditembus dengan kuat, level itu sering berubah menjadi support, dan sebaliknya. Angka bulat seperti 50.000 atau 100.000 dan ",["harga tertinggi sepanjang masa","all-time-high"]," juga sering menjadi area psikologis."],["Trader memakai level ini untuk merencanakan titik masuk, ",["stop loss","stop-loss"],", dan ",["take profit","take-profit"],". Misalnya, stop loss ditaruh sedikit di bawah support, bukan tepat di atasnya, karena harga sering menyentuh level itu sebelum memantul."]],"example":["Misalkan ",["ETH","ethereum"]," tiga kali turun ke kisaran 2.800-2.850 ",["USDT","usdt"]," dalam sebulan, lalu selalu naik lagi. Anda menganggap zona itu sebagai support dan memasang limit buy di 2.860 dengan stop loss di 2.760, sekitar 3,5% di bawah harga masuk. Di sisi atas, harga dua kali tertahan di 3.200, jadi Anda menaruh take profit di 3.180. Potensi untung 320 USDT per ETH dibandingkan risiko 100 USDT per ETH, sehingga ",["rasio risk-reward","risk-reward-ratio"],"-nya sekitar 1:3,2."],"mistakes":["Menganggap support sebagai lantai yang pasti bertahan, padahal level bisa jebol kapan saja.","Menaruh stop loss tepat di level support yang sudah jelas terlihat semua orang.","Menggambar terlalu banyak garis sampai grafik penuh dan setiap harga terlihat seperti level penting."],"faq":[{"q":"Bagaimana cara menentukan support dan resistance?","a":"Cari area di mana harga beberapa kali memantul atau tertahan, terutama di timeframe besar seperti harian atau mingguan. Semakin sering diuji dan semakin besar volumenya, semakin penting area itu."},{"q":"Apa yang terjadi jika support ditembus?","a":"Harga sering melanjutkan penurunan karena stop loss tersentuh, dan support lama bisa berubah menjadi resistance baru. Namun tembusan palsu juga sering terjadi, jadi tunggu konfirmasi penutupan candle."}],"title":"Apa itu support dan resistance? Arti dan cara memakainya","description":"Pahami support dan resistance di grafik kripto, cara menentukannya, dan cara memakainya untuk menaruh stop loss serta take profit.","related":[["candlestick-chart","Grafik candlestick (candle)","Grafik candlestick adalah grafik harga yang menampilkan harga pembukaan, tertinggi, terendah, dan penutupan (OHLC) untuk setiap periode dalam bentuk batang menyerupai lilin."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["all-time-high","All-time high (ATH)","All-time high (ATH) adalah harga tertinggi yang pernah dicapai sebuah aset sejak mulai diperdagangkan."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Satu candle: apa empat hal yang disampaikannya kepada Anda?"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"id","term":"Dollar-cost averaging (DCA)","aka":["DCA","beli rutin","nabung kripto rutin"],"short":"Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu.","body":["Dengan DCA, Anda tidak perlu menebak waktu terbaik untuk membeli. Saat harga turun, nominal yang sama membeli lebih banyak koin; saat harga naik, Anda membeli lebih sedikit. Hasilnya, harga rata-rata Anda menjadi rata-rata tertimbang dari seluruh periode pembelian.",["Strategi ini populer bagi investor jangka panjang karena mengurangi tekanan emosional dan risiko membeli semua modal di puncak. Banyak exchange menyediakan fitur pembelian berulang otomatis di ",["pasar spot","spot-trading"],", termasuk exchange lokal yang mendukung rupiah."],["DCA bukan jaminan untung. Jika aset terus turun dalam jangka panjang, DCA tetap rugi. DCA juga tidak cocok dipakai dengan ",["leverage","leverage"],". Perhatikan biaya per transaksi: pembelian kecil yang terlalu sering bisa tergerus biaya."]],"example":["Misalkan Anda membeli ",["BTC","bitcoin"]," senilai 1.000.000 rupiah setiap bulan selama empat bulan. Harganya berturut-turut 1 miliar, 800 juta, 1 miliar, dan 1,25 miliar rupiah per BTC. Anda mendapat 0,001 + 0,00125 + 0,001 + 0,0008 = 0,00405 BTC dengan total modal 4.000.000 rupiah. Harga rata-rata Anda 4.000.000 dibagi 0,00405, sekitar 987,7 juta rupiah per BTC, lebih rendah dari rata-rata sederhana keempat harga itu, yaitu 1,0125 miliar."],"mistakes":["Menghentikan DCA saat harga turun, padahal justru di fase itu DCA membeli paling banyak koin.","Melakukan DCA pada token kecil tanpa riset sehingga terus membeli aset yang nilainya menyusut.","Memilih nominal terlalu kecil dengan frekuensi tinggi sehingga biaya transaksi memakan porsi besar."],"faq":[{"q":"Apakah DCA lebih baik daripada beli sekaligus?","a":"Tidak selalu. Jika harga terus naik, beli sekaligus di awal bisa memberi hasil lebih baik. DCA unggul dalam mengurangi risiko waktu dan menjaga disiplin."},{"q":"Seberapa sering sebaiknya melakukan DCA?","a":"Mingguan atau bulanan paling umum. Pilih frekuensi yang sesuai arus kas Anda dan pastikan biaya transaksinya kecil dibanding nominal pembelian."}],"title":"Apa itu DCA (dollar-cost averaging) dalam kripto?","description":"Pelajari strategi DCA di kripto: cara kerja beli rutin, contoh hitungan harga rata-rata, kelebihan, dan batasannya.","related":[["hodl","HODL","HODL adalah istilah kripto untuk strategi menyimpan aset dalam jangka panjang tanpa terpengaruh naik turunnya harga harian."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."],["grid-trading-bot","Grid trading bot (bot grid)","Grid trading bot adalah bot otomatis yang memasang serangkaian order beli dan jual di beberapa tingkat harga dalam satu rentang, untuk mengambil untung kecil berulang saat harga naik turun."],["spot-trading","Spot trading (perdagangan spot)","Spot trading adalah jual beli aset kripto secara langsung di harga pasar saat ini, di mana aset benar-benar berpindah ke akun Anda setelah transaksi selesai."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Tentukan berapa banyak kerugian sebelum memutuskan berapa banyak yang dibeli"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"id","term":"Futures USDT-margined (linear futures)","aka":["USDT-M","futures USDT","kontrak linear","linear futures"],"short":"Futures USDT-margined adalah kontrak futures yang memakai stablecoin USDT sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi dihitung langsung dalam USDT secara linear.","body":[["Di kontrak linear, ",["ukuran posisi","position-sizing"]," dinyatakan dalam jumlah koin, misalnya 0,5 ",["BTC","bitcoin"],", dan setiap kenaikan harga 1 ",["USDT","usdt"]," memberi untung atau rugi yang sama besar. Ini membuat perhitungan jauh lebih mudah dibanding ",["kontrak inverse","coin-margined-futures"],", sehingga USDT-margined menjadi pilihan paling umum bagi trader ritel."],["Satu saldo USDT bisa dipakai untuk banyak pasangan sekaligus, misalnya BTC, ",["ETH","ethereum"],", dan SOL, terutama dalam ",["mode cross","cross-margin"]," margin. Margin Anda tidak ikut naik-turun mengikuti harga kripto, karena USDT dirancang setara 1 dolar AS. Tether adalah penerbit USDT."],"Beberapa exchange juga menawarkan kontrak dengan margin USDC atau mata uang lain dengan logika yang sama. Leverage maksimal, ukuran minimal, dan pasangan yang tersedia berbeda di tiap exchange."],"example":"Anda short 2 ETH di kontrak USDT-margined pada harga 3.200 USDT, nilai posisi 6.400 USDT, dengan leverage 8x sehingga margin awal 800 USDT. ETH turun ke 3.050. PnL Anda = 2 x (3.200 - 3.050) = 300 USDT, atau 37,5% dari margin, sebelum biaya dan funding. Jika ETH naik ke 3.350, Anda rugi 2 x 150 = 300 USDT dengan perhitungan yang persis simetris.","mistakes":["Mengira margin USDT berarti posisi bebas risiko volatilitas; posisi tetap rugi jika harga bergerak melawan Anda.","Memakai cross margin untuk banyak pasangan tanpa sadar bahwa kerugian satu posisi bisa menggerus margin posisi lain.","Mengabaikan risiko stablecoin itu sendiri, misalnya jika jaminannya bermasalah."],"faq":[{"q":"Kenapa futures USDT-margined lebih populer?","a":"Perhitungannya linear dan mudah, margin stabil dalam satuan dolar, dan satu saldo USDT bisa dipakai untuk banyak pasangan. Ini cocok bagi kebanyakan trader ritel."},{"q":"Apakah saya perlu memiliki BTC untuk trading futures BTC USDT-margined?","a":"Tidak. Anda cukup menyetor USDT ke akun futures sebagai margin, lalu membuka posisi long atau short pada BTC."}],"title":"Apa itu USDT-margined futures? Arti kontrak linear","description":"Pelajari futures USDT-margined: margin dalam USDT, PnL linear yang mudah dihitung, kelebihannya, dan risiko yang tetap ada.","related":[["coin-margined-futures","Futures coin-margined (inverse futures)","Futures coin-margined adalah kontrak futures yang memakai koin kripto seperti BTC sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi Anda dihitung dalam koin tersebut, bukan dalam USDT."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["usdt","USDT (Tether)","USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto."],["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"id","term":"Open interest (OI)","aka":["OI","posisi terbuka","kontrak terbuka"],"short":"Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu.","body":["Setiap kontrak punya sisi long dan sisi short, jadi open interest menghitung satu sisi saja. Jika trader baru membuka long dan trader baru lain membuka short, OI naik. Jika keduanya menutup posisi, OI turun. Jika satu trader hanya mengalihkan posisinya ke trader lain, OI tidak berubah.",["Berbeda dengan volume yang menghitung aktivitas transaksi, OI menunjukkan berapa banyak uang yang masih tertanam di pasar derivatif. OI yang naik bersama harga sering dibaca sebagai posisi baru yang masuk, sedangkan OI yang turun tajam saat harga jatuh sering menandakan ",["likuidasi","liquidation"]," atau penutupan posisi besar-besaran."],["OI yang sangat tinggi dibanding biasanya, terutama bersama ",["funding rate","funding-rate"]," ekstrem, menunjukkan banyak ",["leverage","leverage"]," di pasar. Kondisi ini bisa membuat pergerakan harga berikutnya lebih tajam. OI bisa dilihat per exchange atau digabung dari banyak exchange melalui situs data."]],"example":["Pada pagi hari, OI ",["BTC","bitcoin"]," ",["perpetual","perpetual-futures"]," di sebuah exchange 2,0 miliar ",["USDT","usdt"],". Harga naik dari 58.000 ke 61.000, dan OI naik ke 2,4 miliar USDT, artinya sekitar 400 juta USDT posisi baru masuk. Malamnya harga turun cepat ke 57.500 dan OI turun ke 1,9 miliar USDT. Penurunan 500 juta USDT itu menunjukkan banyak posisi ditutup atau dilikuidasi, bukan sekadar berpindah tangan."],"mistakes":["Menyamakan open interest dengan volume perdagangan.","Menganggap OI naik pasti bullish, padahal OI naik juga bisa berarti short baru masuk.","Membandingkan OI dalam USDT antar-waktu tanpa sadar perubahan harga ikut mengubah nilai OI."],"faq":[{"q":"Apakah open interest yang tinggi bagus?","a":"OI tinggi menunjukkan banyak modal dan leverage di pasar. Ini menandakan minat besar, tetapi juga meningkatkan risiko pergerakan tajam saat banyak posisi dilikuidasi."},{"q":"Apa beda open interest dan volume?","a":"Volume menghitung semua transaksi dalam periode tertentu, sedangkan open interest menghitung posisi yang masih terbuka pada satu waktu."}],"title":"Apa itu open interest di kripto? Arti dan cara membacanya","description":"Pelajari open interest di futures kripto: cara kerja, beda dengan volume, dan cara membaca OI bersama harga dan funding rate.","related":[["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["long-short-ratio","Rasio long/short (long/short ratio)","Rasio long/short adalah perbandingan antara jumlah akun atau nilai posisi long dan short di pasar futures, dipakai untuk membaca sentimen trader terhadap sebuah aset."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"id","term":"Hot wallet (dompet panas)","aka":["dompet panas","hot wallet"],"short":"Hot wallet adalah dompet kripto yang private key-nya disimpan di perangkat yang terhubung ke internet, seperti aplikasi ponsel atau ekstensi browser, sehingga praktis untuk transaksi harian.","body":[["Contoh hot wallet yang umum adalah MetaMask, Trust Wallet, Phantom, atau dompet bawaan di aplikasi exchange. Karena selalu online, Anda bisa mengirim kripto, swap di ",["DEX","dex"],", atau klaim ",["airdrop","airdrop"]," hanya dalam beberapa detik."],["Kemudahan itu datang dengan risiko. Perangkat yang terhubung internet lebih mudah diserang malware, ekstensi palsu, atau situs ",["phishing","phishing"]," yang meminta Anda menandatangani transaksi berbahaya. Exchange juga menyimpan sebagian dana pengguna di hot wallet untuk melayani penarikan, dan dompet inilah yang paling sering menjadi target peretasan."],["Pola yang banyak dipakai adalah membagi aset. Simpan jumlah kecil di hot wallet untuk kebutuhan sehari-hari, dan pindahkan simpanan besar ke ",["cold wallet","cold-wallet"]," atau ",["hardware wallet","hardware-wallet"]," yang kuncinya tidak pernah menyentuh internet."]],"example":["Bayangkan total ",["aset kripto","cryptocurrency"]," Anda setara 50 juta rupiah. Anda memutuskan menyimpan 5 juta rupiah (10%) di hot wallet di ponsel untuk swap dan biaya gas, sementara 45 juta rupiah (90%) disimpan di hardware wallet. Jika suatu hari Anda tidak sengaja menyetujui kontrak berbahaya dan hot wallet terkuras, kerugian maksimal adalah 5 juta rupiah, bukan seluruh 50 juta rupiah."],"mistakes":["Menyimpan seluruh tabungan kripto di satu hot wallet yang juga dipakai untuk mencoba proyek baru.","Memasang ekstensi dompet dari hasil iklan pencarian tanpa memastikan itu versi resmi.","Menggunakan satu seed phrase yang sama untuk hot wallet dan cold wallet."],"faq":[{"q":"Apakah hot wallet aman?","a":"Hot wallet cukup aman untuk jumlah kecil jika perangkat bersih dan Anda berhati-hati saat menandatangani transaksi. Untuk simpanan besar, cold wallet memberi perlindungan yang lebih kuat."},{"q":"Apakah akun exchange termasuk hot wallet?","a":"Saldo di exchange adalah dompet kustodian, bukan dompet Anda sendiri. Namun exchange memang memakai hot wallet internal untuk memproses penarikan pengguna."}],"title":"Apa itu hot wallet? Arti dompet panas kripto","description":"Arti hot wallet, contoh dompet panas yang populer, risikonya, dan cara membagi aset antara hot wallet dan cold wallet.","related":[["cold-wallet","Cold wallet (cold storage)","Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet."],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"id","term":"Seed phrase (frasa pemulihan)","aka":["frasa pemulihan","recovery phrase","mnemonic phrase","frasa seed"],"short":"Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang.","body":[["Saat membuat ",["dompet non-kustodian","non-custodial-wallet"],", aplikasi menampilkan daftar kata dari kumpulan standar BIP-39. Urutan kata itu adalah kunci induk. Siapa pun yang memegangnya bisa memulihkan seluruh dompet di perangkat mana pun, termasuk semua akun dan semua jaringan di dalamnya."],"Karena kekuatannya sebesar itu, seed phrase harus diperlakukan seperti brankas. Tulis di kertas atau pelat logam, simpan offline, dan jangan pernah mengetikkannya ke situs web, formulir, atau chat. Dompet resmi tidak akan pernah meminta seed phrase Anda melalui email, DM, atau telepon.","Seed phrase berbeda dengan kata sandi aplikasi. Kata sandi hanya membuka aplikasi di satu perangkat, sedangkan seed phrase membuka dompet di mana saja. Lupa kata sandi masih bisa diatasi dengan seed phrase, tetapi kehilangan seed phrase dan perangkat berarti aset tidak bisa dipulihkan."],"example":["Misalnya Anda menyimpan 1.500 ",["USDT","usdt"]," dan 0,8 ",["ETH","ethereum"]," di dompet ponsel. Ponsel hilang di jalan. Anda membeli ponsel baru, memasang aplikasi dompet resmi, memilih pulihkan dompet, lalu memasukkan 12 kata sesuai urutan. Dalam beberapa menit 1.500 USDT dan 0,8 ETH muncul kembali. Sebaliknya, pencuri yang memegang ponsel lama tanpa seed phrase dan tanpa PIN tidak bisa memindahkan aset tersebut."],"mistakes":["Menyimpan seed phrase di catatan ponsel, email, atau cloud yang bisa diakses jika akun dibobol.","Memberikan seed phrase kepada orang yang mengaku sebagai admin atau tim dukungan untuk memperbaiki masalah dompet.","Menulis kata dengan urutan yang salah atau tidak memeriksa ulang ejaannya sebelum menyimpan."],"faq":[{"q":"Apakah seed phrase sama dengan private key?","a":"Tidak persis. Seed phrase adalah bahan dasar yang menghasilkan banyak private key sekaligus. Satu private key hanya mengendalikan satu alamat, sedangkan seed phrase mengendalikan seluruh dompet."},{"q":"Bolehkah seed phrase difoto?","a":"Sebaiknya tidak. Foto bisa tersinkron ke cloud atau terbaca malware, sehingga seed phrase Anda menjadi online dan rentan dicuri."}],"title":"Apa itu seed phrase? Arti frasa pemulihan dompet kripto","description":"Pelajari arti seed phrase atau frasa pemulihan, cara kerjanya, dan cara menyimpannya dengan aman agar aset kripto tidak hilang.","related":[["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"id","term":"Public key (kunci publik)","aka":["kunci publik","public key"],"short":"Public key adalah kunci yang dihitung dari private key dan boleh diketahui orang lain, dipakai jaringan untuk memverifikasi tanda tangan transaksi serta menjadi dasar pembuatan alamat dompet.","body":[["Kriptografi kripto memakai pasangan kunci. ",["Private key","private-key"]," dirahasiakan, public key boleh terbuka. Ketika Anda menandatangani transaksi dengan private key, siapa pun di jaringan bisa memakai public key untuk memastikan tanda tangan itu asli tanpa mengetahui private key-nya."],[["Alamat dompet","wallet-address"]," biasanya bukan public key mentah, melainkan hasil hash dari public key yang lebih pendek dan diberi format tertentu. Di ",["Bitcoin","bitcoin"],", alamat diawali 1, 3, atau bc1; di ",["Ethereum","ethereum"],", alamat adalah 40 karakter heksadesimal dengan awalan 0x yang diambil dari hash public key."],["Untuk penggunaan sehari-hari, Anda cukup membagikan alamat, bukan public key. Namun beberapa fitur lanjutan, misalnya ",["dompet multisig","multisig-wallet"]," atau dompet pantau (watch-only), meminta extended public key (xpub). Xpub tidak bisa memindahkan dana, tetapi bisa memperlihatkan seluruh riwayat dan saldo dompet, jadi tetap perlu dijaga privasinya."]],"example":["Andi mengirim 0,01 BTC ke Budi. Dompet Andi membuat tanda tangan dari private key-nya. Ribuan ",["node","node"]," di jaringan memeriksa tanda tangan itu menggunakan public key Andi dan memastikan alamat pengirim memang memiliki saldo minimal 0,01 BTC ditambah biaya. Setelah valid, transaksi masuk ke blok. Tidak satu pun node pernah melihat private key Andi, tetapi semuanya yakin transaksi itu sah."],"mistakes":["Panik karena public key terlihat di block explorer, padahal public key memang dirancang untuk publik.","Membagikan xpub ke layanan yang tidak dipercaya tanpa sadar bahwa seluruh riwayat dompet ikut terbuka.","Mengira public key bisa dipakai untuk menarik dana dari dompet."],"faq":[{"q":"Apa beda public key dan alamat dompet?","a":"Alamat dompet adalah versi pendek hasil hash dari public key yang dipakai untuk menerima dana. Public key dipakai jaringan untuk memverifikasi tanda tangan."},{"q":"Apakah orang bisa mencuri kripto dengan public key saya?","a":"Tidak. Public key hanya bisa memverifikasi tanda tangan, bukan membuatnya. Untuk memindahkan dana dibutuhkan private key."}],"title":"Apa itu public key? Arti kunci publik di kripto","description":"Arti public key di kripto, hubungannya dengan private key dan alamat dompet, serta kapan xpub perlu dijaga kerahasiaannya.","related":[["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu."],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"id","term":"Transaction hash (TxID)","aka":["TxID","TxHash","hash transaksi","ID transaksi"],"short":"Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer.","body":["Setiap transaksi yang disiarkan ke jaringan mendapat sidik jari berupa hash, biasanya 64 karakter heksadesimal (di jaringan EVM diawali 0x). Hash ini dihitung dari isi transaksi, sehingga dua transaksi berbeda tidak akan punya hash yang sama.",["TxID adalah bukti paling penting saat transfer tidak kunjung tiba. Dengan memasukkannya ke ",["block explorer","block-explorer"]," jaringan yang tepat, Anda bisa melihat apakah transaksi masih menunggu, sudah dikonfirmasi, atau gagal, berapa jumlah yang dikirim, ke alamat mana, dan berapa ",["biaya gas","gas-fee"]," yang dibayar."],["Exchange biasanya menampilkan TxID di riwayat penarikan setelah transaksi disiarkan. Jika riwayat masih menunjukkan proses tanpa TxID, artinya transaksi belum dikirim ke ",["blockchain","blockchain"]," dan masih di antrean internal exchange."]],"example":["Anda menarik 800 ",["USDT","usdt"]," lewat jaringan BNB Smart Chain, tetapi setelah 20 menit saldo tujuan belum bertambah. Anda membuka riwayat penarikan, menyalin TxID yang diawali 0x9c1e, dan memasukkannya ke block explorer BNB Smart Chain. Status menunjukkan berhasil, jumlah 800 USDT, dan alamat penerima cocok. Artinya masalah ada di sisi penerima yang belum mengkredit, sehingga Anda mengirim TxID tersebut ke dukungan exchange tujuan."],"mistakes":["Mencari TxID di block explorer jaringan yang salah lalu mengira transaksinya tidak ada.","Membagikan TxID ke orang yang mengaku bisa mempercepat transaksi dengan imbalan biaya.","Menghubungi dukungan tanpa menyertakan TxID, sehingga proses penelusuran lebih lama."],"faq":[{"q":"Di mana saya bisa menemukan TxID?","a":"Di riwayat penarikan atau deposit exchange, atau di detail transaksi dompet Anda. Dari sana biasanya ada tautan langsung ke block explorer."},{"q":"Apakah TxID berbahaya jika dibagikan?","a":"Tidak. TxID hanya menunjukkan data publik transaksi dan tidak memberi akses ke dompet. Namun jangan percaya orang yang meminta biaya untuk memproses TxID Anda."}],"title":"Apa itu TxID atau transaction hash? Cara melacak transfer","description":"Pelajari arti TxID atau transaction hash, cara memakainya di block explorer, dan langkah saat transfer kripto belum tiba.","related":[["block-explorer","Block explorer","Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi."],["block-confirmations","Konfirmasi blok (block confirmations)","Konfirmasi blok adalah jumlah blok yang sudah ditambahkan sejak transaksi Anda masuk ke blockchain, dan semakin banyak konfirmasi berarti semakin kecil kemungkinan transaksi itu dibatalkan."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Tertulis terkirim, tapi belum sampai. Harus cek ke mana?"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"id","term":"Address poisoning (peracunan alamat)","aka":["peracunan alamat","address poisoning","alamat palsu mirip"],"short":"Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi.","body":[["Pelaku memantau ",["blockchain","blockchain"]," dan melihat alamat yang sering berinteraksi dengan Anda. Lalu mereka membuat alamat baru dengan beberapa karakter awal dan akhir yang sama, misalnya 0x8a4F...c21D. Alamat ini kemudian mengirim transfer debu atau token palsu ke dompet Anda agar muncul di riwayat."],["Kebanyakan dompet dan ",["block explorer","block-explorer"]," menyingkat alamat menjadi beberapa karakter awal dan akhir. Jika Anda terbiasa menyalin alamat tujuan dari riwayat, sangat mudah mengambil alamat palsu yang tampak identik. Begitu dana terkirim, transaksi tidak bisa dibatalkan."],["Cara melindunginya sederhana tetapi harus disiplin. Ambil alamat dari sumber asli, seperti halaman deposit exchange atau buku ",["alamat dompet","wallet-address"],", bukan dari riwayat. Gunakan ",["whitelist penarikan","withdrawal-whitelist"],", beri label pada alamat tepercaya, dan cocokkan juga karakter di bagian tengah alamat."]],"example":["Setiap bulan Anda mengirim 1.000 ",["USDT","usdt"]," dari ",["dompet pribadi","non-custodial-wallet"]," ke alamat deposit exchange yang diawali 0x8a4F dan diakhiri c21D. Suatu hari riwayat dompet menunjukkan transfer 0 USDT dari alamat yang juga diawali 0x8a4F dan diakhiri c21D. Bulan berikutnya Anda menyalin alamat dari riwayat terbaru. Jika tidak memeriksa karakter tengahnya, 1.000 USDT terkirim ke pelaku. Karena Anda mengambil alamat langsung dari halaman deposit exchange, dana tiba di tujuan yang benar."],"mistakes":["Menyalin alamat tujuan dari riwayat transaksi dompet atau block explorer.","Hanya mencocokkan 4 karakter awal dan 4 karakter akhir alamat.","Berinteraksi dengan token tidak dikenal yang tiba-tiba muncul di dompet."],"faq":[{"q":"Apakah transfer debu dari alamat asing berbahaya?","a":"Transfer itu sendiri tidak bisa mengambil dana Anda. Bahayanya muncul jika Anda kemudian menyalin alamat pengirimnya atau berinteraksi dengan token palsu tersebut."},{"q":"Bagaimana cara mencegah address poisoning?","a":"Simpan alamat tepercaya di buku alamat atau whitelist, ambil alamat dari sumber asli, dan periksa seluruh alamat sebelum mengirim jumlah besar."}],"title":"Apa itu address poisoning? Penipuan alamat mirip","description":"Pelajari cara kerja address poisoning, mengapa alamat palsu terlihat mirip, dan cara menghindarinya saat mengirim kripto.","related":[["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"id","term":"Token approval (izin token)","aka":["approval","allowance","izin token","approve"],"short":"Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui.","body":[["Di ",["Ethereum","ethereum"]," dan jaringan EVM lain, ",["DEX","dex"]," atau protokol ",["DeFi","defi"]," tidak bisa langsung mengambil token dari dompet Anda. Anda harus lebih dulu menandatangani transaksi approve untuk token itu. Setelah izin diberikan, kontrak bisa memindahkan token sampai batas allowance tanpa meminta tanda tangan lagi."],"Banyak aplikasi meminta approval tak terbatas agar Anda tidak perlu menyetujui ulang setiap transaksi. Ini praktis, tetapi berisiko. Jika kontrak tersebut diretas, atau ternyata kontrak itu milik penipu, seluruh saldo token tersebut di dompet Anda bisa diambil kapan saja.",["Biasakan memberi approval sebesar kebutuhan transaksi saja jika dompet memungkinkan. Secara berkala, periksa dan cabut (revoke) izin lama lewat alat pengecek approval atau fitur di dompet Anda. Mencabut izin juga memerlukan transaksi dan ",["biaya gas","gas-fee"],"."]],"example":["Anda ingin menukar 100 ",["USDC","usdc"]," di sebuah DEX. Dompet menawarkan approval tak terbatas, tetapi Anda mengubahnya menjadi 100 USDC. Swap berjalan dan allowance kembali mendekati nol. Enam bulan kemudian kontrak DEX itu diretas. Dompet teman Anda yang dulu memberi izin tak terbatas kehilangan 5.000 USDC, sedangkan dompet Anda yang berisi 3.000 USDC tidak tersentuh karena izin yang tersisa sudah tidak ada."],"mistakes":["Menyetujui approval tak terbatas di situs yang baru pertama kali dikunjungi.","Mengira memindahkan dompet ke aplikasi lain otomatis membatalkan approval lama.","Mengira menolak koneksi situs sudah cukup, padahal approval yang pernah diberikan tetap aktif di blockchain."],"faq":[{"q":"Bagaimana cara mencabut token approval?","a":"Gunakan alat pengecek approval tepercaya atau fitur bawaan dompet, pilih izin yang tidak dibutuhkan, lalu tandatangani transaksi revoke. Transaksi ini memerlukan biaya gas."},{"q":"Apakah hardware wallet melindungi dari approval berbahaya?","a":"Tidak sepenuhnya. Jika Anda menyetujui approval berbahaya di hardware wallet, kontrak tetap mendapat izin. Bacalah permintaan approval sebelum menekan setuju."}],"title":"Apa itu token approval? Arti allowance dan risikonya","description":"Pelajari arti token approval atau allowance, mengapa izin tak terbatas berisiko, dan cara mencabut approval lama di dompet Anda.","related":[["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"id","term":"DEX (decentralized exchange)","aka":["decentralized exchange","bursa terdesentralisasi","DEX"],"short":"DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara.","body":[["Berbeda dengan ",["exchange terpusat","centralized-exchange"]," (CEX) seperti Binance atau OKX, DEX tidak memegang dana pengguna. Anda menghubungkan dompet seperti MetaMask atau Phantom, memilih token, lalu menandatangani transaksi swap. Contoh DEX populer adalah Uniswap di ",["Ethereum","ethereum"],", PancakeSwap di BNB Smart Chain, dan Jupiter di Solana."],["Sebagian besar DEX memakai model ",["AMM","amm"]," dengan ",["liquidity pool","liquidity-pool"],", sedangkan sebagian lain memakai ",["order book","order-book"]," on-chain. Ada juga ",["perp DEX","perp-dex"]," seperti Hyperliquid untuk kontrak berjangka perpetual. Karena tidak ada pendaftaran akun, siapa pun bisa membuat token dan pool baru, sehingga pilihan aset sangat luas."],"Kelebihan tersebut datang dengan konsekuensi. Anda membayar biaya gas, harga bisa bergeser karena slippage pada pool yang tipis, token palsu dan rug pull lebih mudah ditemui, dan transaksi bisa terkena MEV. Selalu periksa alamat kontrak token dari sumber resmi proyek."],"example":"Misalnya Anda ingin menukar 500 USDC ke ETH di sebuah DEX. Harga yang ditampilkan 1 ETH = 2.500 USDC, jadi perkiraan hasilnya 0,2 ETH. Anda mengatur toleransi slippage 0,5%, artinya transaksi hanya berjalan jika Anda menerima minimal 0,199 ETH. Fee pool 0,3% dipotong dari swap, ditambah biaya gas jaringan. Jika harga bergerak lebih dari batas itu sebelum transaksi masuk blok, swap gagal dan Anda hanya kehilangan biaya gas.","mistakes":["Membeli token berdasarkan nama atau simbol tanpa memeriksa alamat kontraknya.","Mengatur toleransi slippage terlalu tinggi sehingga mudah menjadi korban sandwich attack.","Lupa menyisakan koin native jaringan untuk membayar biaya gas."],"faq":[{"q":"Apa beda DEX dan CEX?","a":"Di CEX, exchange memegang dana dan mencocokkan order di sistemnya. Di DEX, Anda memegang dana di dompet sendiri dan transaksi dijalankan oleh smart contract."},{"q":"Apakah DEX memerlukan KYC?","a":"Protokol DEX umumnya tidak meminta KYC karena hanya membutuhkan koneksi dompet. Namun beberapa antarmuka web bisa membatasi wilayah tertentu, dan aturan tiap negara berbeda."}],"title":"Apa itu DEX? Arti decentralized exchange kripto","description":"Pelajari arti DEX, beda DEX dan CEX, cara kerja swap dari dompet sendiri, serta risiko slippage, token palsu, dan MEV.","related":[["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["perp-dex","Perp DEX (perpetual on-chain)","Perp DEX adalah decentralized exchange yang menyediakan kontrak berjangka perpetual dengan leverage, di mana margin dan penyelesaian posisi dikelola smart contract atau blockchain, bukan oleh exchange terpusat."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"id","term":"Flash loan (pinjaman kilat)","aka":["pinjaman kilat","flash loan"],"short":"Flash loan adalah pinjaman tanpa jaminan di DeFi yang harus dipinjam dan dikembalikan dalam satu transaksi yang sama; jika tidak dilunasi, seluruh transaksi dibatalkan otomatis.","body":[["Di ",["blockchain","blockchain"]," seperti ",["Ethereum","ethereum"],", satu transaksi bisa berisi banyak langkah. Flash loan memanfaatkan sifat ini: kontrak meminjamkan dana, menjalankan langkah-langkah yang Anda tulis, lalu memeriksa apakah pinjaman beserta fee sudah kembali. Jika belum, transaksi gagal seolah tidak pernah terjadi, sehingga pemberi pinjaman tidak menanggung risiko gagal bayar."],["Penggunaan yang sah antara lain ",["arbitrase","arbitrage"]," antar ",["DEX","dex"],", melunasi pinjaman lalu memindahkan jaminan dalam sekali jalan, atau melakukan ",["likuidasi","liquidation"]," posisi orang lain tanpa modal besar. Aave adalah salah satu protokol yang menyediakan flash loan."],["Flash loan juga sering muncul dalam berita eksploitasi. Penyerang meminjam dana sangat besar untuk sementara memanipulasi harga di pool kecil yang dipakai sebagai oracle oleh protokol lain. Masalah sebenarnya adalah desain oracle atau kontrak yang lemah, bukan flash loan itu sendiri. Untuk pengguna biasa, flash loan memerlukan kemampuan menulis ",["smart contract","smart-contract"],"."]],"example":"Misalnya sebuah token stabil dihargai 1,000 USDC di DEX A dan 1,004 USDC di DEX B. Sebuah kontrak meminjam 1.000.000 USDC lewat flash loan dengan fee contoh 0,05% atau 500 USDC. Kontrak membeli token di DEX A dan langsung menjualnya di DEX B, menghasilkan selisih kotor sekitar 4.000 USDC. Setelah mengembalikan 1.000.500 USDC, sisa keuntungan sekitar 3.500 USDC sebelum slippage dan biaya gas. Jika hasilnya kurang dari pinjaman, seluruh transaksi dibatalkan.","mistakes":["Mengira flash loan bisa dipakai untuk meminjam uang lalu menyimpannya lebih lama.","Membeli bot atau script flash loan dari orang tak dikenal yang menjanjikan keuntungan pasti.","Menyalahkan flash loan sebagai penyebab peretasan, padahal celahnya ada pada protokol yang dieksploitasi."],"faq":[{"q":"Apakah flash loan memerlukan jaminan?","a":"Tidak. Jaminannya adalah aturan bahwa pinjaman harus kembali dalam transaksi yang sama, jika tidak transaksi dibatalkan."},{"q":"Apakah orang biasa bisa memakai flash loan?","a":"Secara teknis bisa, tetapi biasanya memerlukan smart contract sendiri. Tawaran bot flash loan siap pakai di media sosial sering kali penipuan."}],"title":"Apa itu flash loan? Arti pinjaman kilat di DeFi","description":"Pelajari arti flash loan, cara kerjanya dalam satu transaksi, kegunaan seperti arbitrase, dan kaitannya dengan eksploitasi DeFi.","related":[["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya."],["oracle","Oracle blockchain","Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut."],["mev","MEV (maximal extractable value)","MEV adalah keuntungan tambahan yang bisa diambil oleh pihak yang mengatur urutan transaksi dalam sebuah blok, misalnya dengan mendahului atau mengapit transaksi pengguna lain."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"id","term":"Wrapped token (token terbungkus)","aka":["token wrapped","WBTC","WETH","token terbungkus"],"short":"Wrapped token adalah token yang mewakili aset lain dengan perbandingan 1:1, misalnya WBTC yang mewakili BTC di Ethereum, sehingga aset itu bisa dipakai di jaringan atau aplikasi yang tidak mendukungnya secara langsung.","body":[[["Bitcoin","bitcoin"]," tidak bisa dipakai langsung di ",["DeFi","defi"]," ",["Ethereum","ethereum"],". Solusinya, sebuah kustodian atau protokol menahan BTC asli lalu menerbitkan token ERC-20 seperti WBTC dengan jumlah yang sama. Saat token dikembalikan dan dibakar, BTC asli dilepas."],"Ada juga wrapped token untuk koin native di jaringannya sendiri. ETH bukan token ERC-20, jadi banyak protokol memakai WETH yang bisa ditukar 1:1 dengan ETH kapan saja melalui kontrak. Hal yang sama berlaku untuk WBNB, WSOL, dan lainnya.","Nilai wrapped token bergantung pada pihak atau mekanisme yang menjaga cadangan asli. Pada WBTC dan sejenisnya, ada risiko kustodian. Pada token hasil bridge, ada risiko peretasan bridge. Jika cadangan bermasalah, harga wrapped token bisa lepas dari aset aslinya. Satu aset juga bisa punya beberapa versi wrapped yang berbeda di satu jaringan."],"example":"Misalnya Anda memegang 0,5 BTC dan ingin menjadikannya jaminan di protokol lending Ethereum. Anda menukar 0,5 BTC menjadi WBTC melalui layanan yang mendukung, dengan biaya contoh 0,001 BTC, sehingga menerima 0,499 WBTC. Token ini lalu disetor sebagai jaminan. Saat ingin kembali ke BTC asli, Anda menukar 0,499 WBTC kembali ke BTC dan kembali membayar biaya serta gas.","mistakes":["Mengira semua token berlabel BTC di jaringan lain memiliki jaminan dan risiko yang sama.","Mengirim wrapped token ke exchange yang hanya mendukung versi lain di jaringan berbeda.","Lupa bahwa WETH perlu di-unwrap jika aplikasi tujuan hanya menerima ETH native."],"faq":[{"q":"Apakah WBTC sama dengan BTC?","a":"Nilainya dirancang 1:1, tetapi WBTC adalah token di Ethereum yang bergantung pada kustodian penyimpan BTC asli. Pemegang WBTC tidak memegang BTC secara langsung."},{"q":"Mengapa perlu WETH jika sudah punya ETH?","a":"Banyak smart contract hanya bekerja dengan standar ERC-20. WETH adalah ETH yang dibungkus ke standar itu dan bisa ditukar balik 1:1."}],"title":"Apa itu wrapped token? Arti WBTC dan WETH","description":"Pelajari arti wrapped token seperti WBTC dan WETH, cara kerjanya, dan risiko kustodian atau bridge di balik token terbungkus.","related":[["cross-chain-bridge","Cross-chain bridge (jembatan antar-chain)","Cross-chain bridge adalah protokol yang memindahkan aset atau data dari satu blockchain ke blockchain lain, misalnya memindahkan USDC dari Ethereum ke Arbitrum."],["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi."],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"id","term":"KYC (Know Your Customer)","aka":["Know Your Customer","verifikasi identitas","e-KYC"],"short":"KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh.","body":[["Tujuan KYC adalah mencegah pencucian uang, pendanaan terorisme, dan penipuan identitas. Bursa resmi wajib mengenali nasabahnya. Di Indonesia, pedagang ",["aset kripto","cryptocurrency"]," berizin kini diawasi OJK sejak Januari 2025, setelah sebelumnya di bawah Bappebti, dan proses KYC biasanya memakai KTP serta verifikasi wajah."],["Bursa global biasanya punya beberapa level verifikasi. Level dasar membuka setoran dan perdagangan, level lanjut membuka batas penarikan lebih besar, ",["P2P","p2p-trading"],", atau produk derivatif. Persyaratan dan batas setiap level berbeda antarbursa dan antarnegara."],"KYC juga berarti Anda menyerahkan data pribadi. Lakukan hanya di aplikasi atau situs resmi bursa, jangan lewat tautan dari pesan pribadi. Jangan pernah meminjamkan akun yang sudah terverifikasi atas nama Anda kepada orang lain, karena semua transaksi tercatat atas identitas Anda."],"example":["Misalkan sebuah bursa membatasi penarikan akun tanpa verifikasi lanjut hingga setara 2.000 ",["USDT","usdt"]," per hari. Anda menjual koin dan punya saldo 7.500 USDT yang ingin ditarik. Tanpa naik level, Anda butuh empat hari: tiga hari masing-masing 2.000 USDT dan satu hari 1.500 USDT. Jika Anda menyelesaikan verifikasi lanjut lebih dulu, misalnya mengunggah bukti alamat, seluruh 7.500 USDT bisa ditarik sekaligus. Karena itu sebaiknya Anda menyelesaikan KYC sebelum butuh dana, bukan saat terdesak."],"mistakes":["Mengirim foto KTP dan selfie lewat chat kepada orang yang mengaku petugas bursa.","Menunda KYC sampai saat ingin menarik dana dalam jumlah besar.","Menyewakan atau meminjamkan akun terverifikasi kepada orang lain."],"faq":[{"q":"Kenapa bursa kripto wajib KYC?","a":"Karena aturan anti pencucian uang mewajibkan penyedia jasa aset kripto mengenali nasabah. Bursa yang tidak menjalankan KYC berisiko dibekukan atau diblokir regulator."},{"q":"Berapa lama proses KYC?","a":"Verifikasi otomatis sering selesai dalam hitungan menit, tetapi bisa memakan waktu lebih lama jika dokumen buram atau perlu tinjauan manual. Pastikan foto dokumen jelas dan data sesuai identitas."}],"title":"Apa itu KYC di bursa kripto? Arti dan prosesnya","description":"Pahami arti KYC di bursa kripto, dokumen yang biasanya diminta, level verifikasi, dan cara menjaga data pribadi Anda.","related":[["aml","AML (anti pencucian uang)","AML adalah kumpulan aturan dan prosedur untuk mencegah dana hasil kejahatan dicuci lewat sistem keuangan, termasuk lewat bursa dan transfer aset kripto."],["travel-rule","Travel rule","Travel rule adalah aturan yang mewajibkan penyedia jasa aset kripto mengirim dan menerima data pengirim serta penerima bersama transfer kripto, mengikuti Rekomendasi 16 FATF."],["no-kyc-exchange","Bursa tanpa KYC (no-KYC exchange)","Bursa tanpa KYC adalah platform yang mengizinkan Anda berdagang atau menarik kripto tanpa verifikasi identitas, biasanya dengan batas penarikan tertentu atau sebagai bursa terdesentralisasi."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."],["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"Bagaimana cara kerja KYC dan kepada siapa identitas diberikan?"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"id","term":"Demo trading (akun demo)","aka":["akun demo","paper trading","trading simulasi","testnet"],"short":"Demo trading adalah mode latihan di bursa yang memakai saldo virtual, sehingga Anda bisa mencoba spot, futures, leverage, atau bot dengan harga pasar nyata tanpa mempertaruhkan uang sungguhan.","body":[["Banyak bursa besar menyediakan akun demo atau mode simulasi dengan saldo virtual, misalnya puluhan ribu ",["USDT","usdt"]," tiruan. Anda bisa berlatih memasang ",["limit order","limit-order"],", ",["stop loss","stop-loss"],", ",["take profit","take-profit"],", memilih ",["margin terisolasi","isolated-margin"]," atau silang, dan melihat bagaimana ",["harga likuidasi","liquidation-price"]," berubah saat leverage dinaikkan."],"Demo trading berguna untuk memahami tampilan dan mekanisme sebelum memakai dana sungguhan. Namun ada keterbatasan: eksekusi di akun demo bisa lebih mulus daripada pasar nyata, likuiditas dan slippage tidak selalu realistis, dan yang paling penting, tekanan emosinya berbeda.","Gunakan demo untuk menguji proses, bukan untuk membuktikan bahwa strategi pasti menguntungkan. Setelah beralih ke akun nyata, mulai dengan nominal kecil dan pertahankan aturan manajemen risiko yang sama."],"example":"Misalkan di akun demo Anda membuka long BTC senilai 5.000 USDT dengan margin 500 USDT, artinya leverage 10x, di harga 60.000. Anda melihat harga likuidasi sekitar 54.300 dengan margin terisolasi, tergantung aturan margin pemeliharaan bursa. Lalu Anda mencoba leverage 25x dengan margin 200 USDT untuk posisi yang sama, dan harga likuidasi naik ke sekitar 57.900. Dari latihan ini Anda belajar bahwa leverage tinggi membuat penurunan sekitar 3,5% saja sudah cukup untuk melikuidasi posisi.","mistakes":["Mengira hasil bagus di akun demo pasti terulang di akun nyata.","Langsung memakai ukuran posisi besar di akun nyata setelah sukses di demo.","Berlatih tanpa stop loss karena merasa tidak ada uang yang dipertaruhkan."],"faq":[{"q":"Apakah akun demo bursa gratis?","a":"Umumnya gratis dan memakai saldo virtual yang bisa direset. Ketersediaan dan fitur demo berbeda antarbursa dan antarproduk."},{"q":"Berapa lama sebaiknya latihan di akun demo?","a":"Tidak ada patokan waktu pasti. Lanjutkan sampai Anda paham cara memasang order, menghitung ukuran posisi, dan membaca harga likuidasi tanpa ragu."}],"title":"Apa itu demo trading kripto? Latihan dengan akun demo","description":"Pelajari manfaat demo trading di bursa kripto, cara berlatih leverage dan likuidasi, serta keterbatasan akun demo.","related":[["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["copy-trading","Copy trading","Copy trading adalah fitur bursa yang otomatis meniru posisi trader lain, yang biasa disebut lead trader, ke akun Anda sesuai modal dan pengaturan yang Anda pilih."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Leverage 10x: lebih banyak uang, atau lebih banyak risiko?"},"coin":null,"tool":null,"cta":true}});
